head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    wframe1.setSrc("test11_2.xml");
};
scwin.trigger2_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var rowJSON = {
        "addr": "서울시",
        "name": "손예진",
        "rowStatus": "R"
    };
    //popup에 넘길 data객체. 
    var dataObj = {
        type: "json", // 데이터 타입. "xml","string","json","array" 
        data: rowJSON, // 전달 데이터 객체. 
        name: "paramTest" // 변수명. popup에서 $w.getParameter( "paramTest" )로 깨내올 수 있다. 
    };
    var opts = {
        "id": "popup_window",
        "type": "browserPopup",
        "width": 500 + "px",
        "height": 300 + "px",
        "top": 250,
        "left": 250,
        "popupName": "윈도우 팝업[window type]",
        "modal": false,
        "useModalStack": false,
        "useIFrame": false,
        "style": "",
        "srcData": "",
        "destData": "",
        "dataObject": dataObj,
        "xml": "",
        "resizable": false,
        "status": false,
        "menubar": false,
        "scrollbars": false,
        "title": "focusTest",
        "useMaximize": false,
        "closeAction": "",
        "className": "",
        "fullscreen": false,
        "useControl": false,
        "alwaysOnTop": false,
        "frameMode": ""
    };
    var options = {
        id: "popup1",
        type: "browserPopup ",
        width: 300 + "px",
        height: 300 + "px",
        top: 100 + "px",
        left: 100 + "px",
        popupName: "Test111",
        modal: true,
        style: "",
        resizable: true,
        status: false,
        menubar: false,
        scrollbars: false,
        title: false,
        useMaximize: true,
        dataObject: dataObj
    };
    $p.openPopup("windoContainer_createWindow_WEFF-585_(WSQ-3939)_sub2_auto.xml", opts);
};
